    try std.testing.expectError(error.InvalidFrameEncoding, world.Actuation.Membrane.execute(.{
        .policy = policy,
        .intent = intent,
        .envelope = wrong_request_envelope,
        .descriptor = descriptor,
        .actuator = .{ .fixture = .{ .frame_response_fingerprint = 0x4207 } },
